export const cohortGroups=[{id:'development',label:'Development'},{id:'holdout',label:'Holdout'},{id:'supplement',label:'Additional 24'},{id:'legacy',label:'Legacy 24'},{id:'private',label:'Owner-only'},...Object.entries(newCohortLabels).map(([id,label])=>({id,label}))];
export const featureGroups=[
 ['demographic','Demographics','Stated age and pronouns. Pronouns are not a gender classification.'],
 ['geography','Location','First US state named in the location field; locality wording is counted only when explicit.'],
 ['culture','Family, culture & languages','Mentions in the family/cultural narrative, including partial or family language exposure. Not inferred ethnicity, religion or fluency.'],
 ['family','Family context','Household wording and family-history topics; history does not establish the present household.'],
 ['finance','Financial background','Explicit wording in the household-finances narrative; overlapping contexts, not income bands or poverty estimates.'],
 ['school','School context','Explicit wording in the school narrative. School types may overlap.'],
 ['riasec','Six interests','Recorded simulation answers to the official interest inventory. Means are out of 40, not aptitude or percentiles.'],
 ['interest','Interests & activities','Editorial themes in the stated enjoys/activities lists. No inference from career outcomes.'],
 ['skill','Described skills & strengths','Editorial themes in the biography’s demonstratedSkills list. These are fictional descriptions, not measured skill scores.'],
 ['motivation','Motivations & ambitions','Narrative themes and separately labeled applied priority choices. No motivation inferred from family circumstances.'],
 ['style','Characteristics & working style','Topics mentioned in self-description, enjoys, avoids and struggles; not personality-test classifications.'],
 ['mental','Mental health & well-being','Named topics in the narrative, potentially historical or about family. Mentions are not student diagnoses or prevalence. Silence means not stated.'],
 ['learning','Learning & neurodivergence','Explicit topic mentions, kept separate from mental-health diagnoses. Context and timing remain in the source.'],
 ['physical','Physical health & access','Explicit physical-health/access topics; mentions do not establish current functional limitations.'],
 ['support','Supports & opportunities','People, services and opportunities explicitly described. A counselor mention does not establish a condition.'],
 ['constraint','Constraints & unfamiliar work','Current practical constraints and access wording. Unfamiliar activities remain available in full detail.'],
 ['recording','Evidence availability','What is actually recorded, distinct from narrative themes. No aptitude or clinical assessment is available.']
].map(([id,label,note])=>({id,label,note}));
const f=[];const rule=(group,id,label,scope,pattern)=>f.push({group,id:group+'-'+id,label,kind:'mention',scope,pattern:new RegExp('\\b(?:'+pattern.source+')',pattern.flags)});
