for(const[id,label,re]of [['autonomy','Autonomy / independence / choice',/independen|autonom|choice|control|own (?:time|money|space|schedule|decisions)|choos/i],['stability','Stability / predictability / security',/stabil|steady|predictab|secur|reliab|dependab|routine/i],['learning','Curiosity / understanding / learning',/learn|understand|curios|explain|investigat|discover|explor/i],['creative','Creativity / expression / making',/creat|express|\bmak(?:e|ing)|\bart\b|design|writ|music|object/i],['contribution','Contribution / usefulness / service',/useful|help|serv|contribut|benefit|care for/i],['connection','Relationships / belonging',/friend|famil|relationship|belong|connection|people|together|trust/i],['fairness','Fairness / inclusion / voice',/fair|inclus|equal|justice|voice|respect/i],['balance','Time / space / manageable pace',/time|space|manageable|pace|balance|quiet|ordinary life|privacy/i],['earning','Income / earning / affordability',/\bearn|money|income|saving|afford|\bpaid\b|financial|spending/i]])rule('motivation',id,label,'motivation',re);
