for(const[id,label,re]of [['hearing','Hearing difference / Deafness named',/hearing (?:loss|difference|aids|technology)|\bDeaf\b|hard of hearing/i],['mobility','Mobility / wheelchair / motor-condition topic',/wheelchair|mobility|cerebral palsy|spinal.{0,15}injur/i],['diabetes','Diabetes named',/diabet/i],['asthma','Asthma named',/\basthma\b/i],['arthritis','Arthritis named',/\barthritis\b/i],['other','Other explicit chronic-health wording',/chronic|epilep|seizure|migraine|sickle.cell|vision loss|visual impairment/i]])rule('physical',id,label,'all',re);
for(const[id,label,re]of [['family','Family / guardian support',/parent|mother|father|aunt|uncle|grand|guardian|sibling|sister|brother|cousin/i],['teacher','Teacher / school staff support',/teacher|school|tutor|instructor|adviser|advisor/i],['counsel','Counselor / mental-health care support',/counsel|mental.health|psychotherap|psycholog|psychiatr/i],['peer','Peer / friend support',/friend|peer|classmate|study group/i],['community','Community / library / group access',/community|librar|club|group|congregation|coach|program|center|centre|church/i]])rule('support',id,label,'support',re);
