for(const[fact,label]of [['structuredSkill','Optional experience answers applied in main replay'],['authoredSkill','Authored optional experience answers available'],['narrativeSkill','Narrative skills description available'],['fullInterest','Complete official interest inventory recorded'],['biography','Biography fields available'],['clinical','Standardized clinical assessment available'],['aptitude','Validated aptitude measurement available']])f.push({group:'recording',id:'recording-'+fact,label,kind:'fact',fact});
export const featureDefinitions=f;
const pathLabels={family:'Household',finances:'Household finances',geography:'Location',cultureLanguages:'Family, culture & language context',school:'School',accessOpportunities:'Access to opportunities',enjoys:'Enjoys',avoids:'Avoids',activities:'Activities',demonstratedSkills:'Described skills',unfamiliarActivities:'Unfamiliar activities',motivations:'Motivations',ambitions:'Ambitions',struggles:'Struggles',supports:'Supports',practicalConstraints:'Practical constraints',selfDescription:'Self-description',openQuestions:'Open questions',variationTags:'Author’s variation tags'};
export function biographySegments(b={}){const out=[];const add=(path,label,v)=>{if(Array.isArray(v))v.forEach((x,i)=>add(path+'.'+i,label,x));else if(typeof v==='string'&&v.trim())out.push({path,label,text:v});};for(const[k,v]of Object.entries(b.background||{}))add('background.'+k,pathLabels[k]||k,v);for(const[k,v]of Object.entries(b.currentLife||{}))add('currentLife.'+k,pathLabels[k]||k,v);for(const[k,v]of Object.entries(b))if(['selfDescription','openQuestions','variationTags'].includes(k))add(k,pathLabels[k],v);for(const[t,i]of(b.timeline||[]).map((t,i)=>[t,i]))add('timeline.'+i+'.story','History · age '+t.ages,t.story);return out;}
const starts=(p,...prefixes)=>prefixes.some(s=>p===s||p.startsWith(s+'.'));
function inScope(s,scope){const p=s.path;return scope==='all'||({culture:starts(p,'background.cultureLanguages'),geography:starts(p,'background.geography'),family:starts(p,'background.family'),finance:starts(p,'background.finances'),school:starts(p,'background.school'),interest:starts(p,'currentLife.enjoys','currentLife.activities'),skill:starts(p,'currentLife.demonstratedSkills'),motivation:starts(p,'currentLife.motivations','currentLife.ambitions'),style:starts(p,'selfDescription','currentLife.enjoys','currentLife.avoids','currentLife.struggles'),support:starts(p,'currentLife.supports','background.accessOpportunities'),constraint:starts(p,'currentLife.practicalConstraints','background.accessOpportunities')})[scope]===true;}
const stateNames=['Alabama','Alaska','Arizona','Arkansas','California','Colorado','Connecticut','Delaware','Florida','Georgia','Hawaii','Idaho','Illinois','Indiana','Iowa','Kansas','Kentucky','Louisiana','Maine','Maryland','Massachusetts','Michigan','Minnesota','Mississippi','Missouri','Montana','Nebraska','Nevada','New Hampshire','New Jersey','New Mexico','New York','North Carolina','North Dakota','Ohio','Oklahoma','Oregon','Pennsylvania','Rhode Island','South Carolina','South Dakota','Tennessee','Texas','Utah','Vermont','Virginia','Washington','West Virginia','Wisconsin','Wyoming'];
export function primaryState(text=''){return stateNames.map(value=>({value,index:new RegExp('\\b'+value+'\\b','i').exec(text)?.index??Infinity})).filter(r=>Number.isFinite(r.index)).sort((a,b)=>a.index-b.index||b.value.length-a.value.length)[0]?.value||null;}
function factEvidence(def,row){const b=row.biography,p=row.interest;let hit=false,path='',text='';switch(def.fact){case'age':{const age=Number.isFinite(b.age)?b.age:null;hit=(age===null?'unknown':age<16?'under16':age===16?'16':'17plus')===def.value;path='age';text=age===null?'Not stated':String(age);break;}case'pronouns':{const v=b.pronouns||'Not stated',known=['she/her','he/him','they/them','he/they','she/they'];hit=(known.includes(v)?v:'other / not stated')===def.value;path='pronouns';text=v;break;}case'location':hit=(row.primaryState==='Texas'?'Texas':row.primaryState?'Other US state':'Not identified')===def.value;path='background.geography';text=b.background?.geography||'Not stated';break;case'lead':hit=p.complete&&!p.flat&&!p.nearFlat&&p.positive.includes(def.value);path='officialInterest';text='Six scores: '+p.raw.join(', ')+'; strongest theme '+def.value;break;case'open':hit=p.complete&&(p.flat||p.nearFlat);path='officialInterest';text='Complete but flat or nearly flat profile; no strongest theme assigned.';break;case'priority':hit=(row.appliedPriorities||[]).includes(def.value);path='experimentState.priorities';text=def.label;break;case'authoredSkill':hit=Object.keys(row.authoredSkills||{}).length>0;path='response.experience';text=JSON.stringify(row.authoredSkills);break;case'structuredSkill':hit=Object.keys(row.recordedSkills||{}).length>0;path='recordedSkills';text=JSON.stringify(row.recordedSkills);break;case'narrativeSkill':hit=!!b.currentLife?.demonstratedSkills?.length;path='currentLife.demonstratedSkills';text=(b.currentLife?.demonstratedSkills||[]).join(' · ');break;case'fullInterest':hit=p.complete;path='officialInterest';text=p.answered+' of 60 official items answered';break;case'biography':hit=!!Object.keys(b.background||{}).length&&!!Object.keys(b.currentLife||{}).length;path='biography';text='Frozen fictional biography with current-life and background fields';break;case'clinical':case'aptitude':return[];}return hit?[{path,label:def.label,text}]:[];}
export function cohortRow(c){const b=structuredClone(c.biography||{}),interest=scoreOnetInterest(c.experimentState||{}),row={id:c.id,name:b.name||c.id,phase:cohortGroups.some(g=>g.id===c.phase)?c.phase:'private',biography:b,interest:{raw:interest.raw,answered:interest.answered,complete:interest.complete,flat:interest.flat,nearFlat:interest.nearFlat,positive:interest.positive},scores:interest.raw,recordedSkills:structuredClone(c.experimentState?.profileJourney?.skills||{}),recordedPreferences:structuredClone(c.experimentState?.profileJourney?.answers||{}),authoredSkills:authoredExperience(c),appliedPriorities:structuredClone(c.experimentState?.priorities||[]),cohort049:structuredClone(c.cohort049||null),primaryState:primaryState(b.background?.geography),segments:biographySegments(b),features:{},source:c.id.startsWith('private-')?{classification:'Owner-only fictional model',authenticated:true}:{classification:'Public frozen fictional model',url:'./lives/'+c.id+'.json'}};
 for(const def of featureDefinitions){if(def.kind==='score')continue;const evidence=def.kind==='fact'?factEvidence(def,row):row.segments.filter(s=>inScope(s,def.scope)&&def.pattern.test(s.text)&&!(['mental','learning','physical'].includes(def.group)&&/^(?:no (?:diagnosed |history of |known )?|not (?:diagnosed |a diagnosis)|without (?:a )?diagnos)/i.test(s.text.trim())));if(evidence.length)row.features[def.id]=evidence;}return row;}
export function filterCohort(rows,{cohort='all',query='',feature='all'}={}){const q=query.trim().toLocaleLowerCase();return selectCohortPopulation(rows,cohort).filter(r=>(feature==='all'||r.features[feature]?.length)&&(!q||[r.id,r.name,JSON.stringify(r.biography),...Object.keys(r.features).map(id=>featureDefinitions.find(f=>f.id===id)?.label||id)].join(' ').toLocaleLowerCase().includes(q)));}
export function distributionCell(rows,def){if(!rows.length)return{value:null,count:0,n:0,ids:[]};if(def.kind==='score'){const valid=rows.filter(r=>r.interest.complete&&Number.isFinite(r.scores[def.axis]));return{value:valid.length?valid.reduce((sum,r)=>sum+r.scores[def.axis],0)/valid.length:null,count:valid.length,n:rows.length,ids:valid.map(r=>r.id)};}const matched=rows.filter(r=>r.features[def.id]?.length);return{value:matched.length/rows.length,count:matched.length,n:rows.length,ids:matched.map(r=>r.id)};}
export function cohortDistribution(rows,group='all'){const groups=[{id:'all',label:'Full selection'},...cohortGroups].map(g=>({...g,rows:g.id==='all'?rows:rows.filter(r=>r.phase===g.id)}));return{models:rows.length,groups:groups.map(g=>({id:g.id,label:g.label,n:g.rows.length})),features:featureDefinitions.filter(f=>group==='all'||f.group===group).map(def=>({definition:def,cells:groups.map(g=>({cohort:g.id,...distributionCell(g.rows,def)}))}))};}
export function scopeLabels(row,group){return featureDefinitions.filter(f=>f.group===group&&row.features[f.id]?.length).map(f=>f.label);}
